{
  "passageId": "laozi-interpretations",
  "items": [
    {
      "id": "R1",
      "type": "BACKGROUND",
      "otherName": "",
      "reason": "여러 나라가 패권을 다투던 혼란기는 한비자가 법치에 의한 부국강병을 추구한 시대적 배경이다."
    },
    {
      "id": "R2",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "『노자』에 대한 해석은 한비자가 추구한 법치 사상을 정당화하고 뒷받침하는 근거로 제시된다."
    },
    {
      "id": "R3",
      "type": "VIEW_AGREEMENT",
      "otherName": "",
      "reason": "『노자』와 한비자는 도를 만물의 근원으로 이해한다는 점에서 같은 견해를 보인다."
    },
    {
      "id": "R4",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "모든 현상이 도의 영향을 받는다는 포괄적 설명을 인간 사회의 일의 성패라는 세부 내용으로 구체화한다."
    },
    {
      "id": "R5",
      "type": "CONCESSION",
      "otherName": "",
      "reason": "한비자가 이해한 도의 항상성은 영원한 존재를 뜻하지만 모습과 이치의 고정성까지 뜻하지는 않는다는 한계를 밝힌다."
    },
    {
      "id": "R6",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "도가 고정되어 있지 않다는 성질을 근거로 때와 상황에 따라 유연하게 변화한다고 설명한다."
    },
    {
      "id": "R7",
      "type": "CONDITION",
      "otherName": "",
      "reason": "가변성을 지녀 일정한 곳에만 있지 않는 것이 도가 모든 사물의 근거가 되기 위한 필요조건으로 연결된다."
    },
    {
      "id": "R8",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "가변성으로 특정한 곳에 한정되지 않는다는 설명이 도가 만물의 존재와 본질의 근거일 수 있다는 판단을 뒷받침한다."
    },
    {
      "id": "R9",
      "type": "APPLICATION",
      "otherName": "",
      "reason": "도의 가변성이라는 원리를 통치 영역에 가져와 통치술도 고정되어서는 안 된다고 주장한다."
    },
    {
      "id": "R10",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "도가 개별 법칙의 통합이라는 이해를 근거로 도에 시비 판단의 근거라는 의미를 부여한다."
    },
    {
      "id": "R11",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "도가 개별 법칙을 포괄한다는 성질로부터 다양한 사건의 시비 판단 기준이 될 수 있다는 결론을 이끌어 낸다."
    },
    {
      "id": "R12",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "도가 사건의 시비 판단 기준이 된다는 점을 이유로 도에 근거하여 입법해야 한다는 주장을 세운다."
    },
    {
      "id": "R13",
      "type": "VIEW_AGREEMENT",
      "otherName": "",
      "reason": "한비자는 인간의 욕망이 사회 혼란의 원인이라는 『노자』의 견해를 받아들인다."
    },
    {
      "id": "R14",
      "type": "VIEW_DIFFERENCE",
      "otherName": "",
      "reason": "욕망을 없애야 하는지에 관하여 『노자』와 한비자의 다른 입장을 나란히 제시한다."
    },
    {
      "id": "R15",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "인간이 욕망을 필연적으로 지닌다는 사실을 이유로 욕망을 제어할 법이 필요하다는 당위를 주장한다."
    },
    {
      "id": "R16",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "도의 가변성을 통해 통치술의 변화를 주장한 내용은 『노자』 해석으로 법치 사상을 뒷받침한 구체적 양상이다."
    },
    {
      "id": "R17",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "도에 근거한 입법과 법을 통한 욕망 제어는 『노자』 해석으로 법치 사상을 뒷받침했다는 설명을 구체화한다."
    },
    {
      "id": "R18",
      "type": "BACKGROUND",
      "otherName": "",
      "reason": "인간 삶의 올바른 길이라는 유학의 도 개념은 송나라 이후 유학자들이 도가의 도에 주목한 사상적 배경이다."
    },
    {
      "id": "R19",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "왕안석의 주석은 송나라 이후 유학의 관점에서 전개된 『노자』 주석의 구체적 사례이다."
    },
    {
      "id": "R20",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "오징의 주석은 유학의 도를 기반으로 『노자』를 해석한 흐름을 보여 주는 사례이다."
    },
    {
      "id": "R21",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "설혜의 주석은 유학의 관점에서 『노자』 주석을 전개했다는 일반적 설명을 구체적으로 보여 준다."
    },
    {
      "id": "R22",
      "type": "BACKGROUND",
      "otherName": "",
      "reason": "송나라의 정치적 갈등과 개혁 분위기는 왕안석이 『노자주』를 저술한 시대적 배경이다."
    },
    {
      "id": "R23",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "기가 만물의 물질적 근원이라는 이해를 기의 작용에 의한 사물 형성이라는 내용으로 자세히 푼다."
    },
    {
      "id": "R24",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "현상 세계와 현실 사회가 변화한다는 이해를 근거로 사회 제도와 규범도 새롭게 해야 한다는 주장을 세운다."
    },
    {
      "id": "R25",
      "type": "CRITIQUE",
      "otherName": "",
      "reason": "원문은 왕안석이 인위 제거를 주장한 『노자』를 비판하며 적극적 개입의 필요성을 제시했다고 명시한다."
    },
    {
      "id": "R26",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "인간의 적극적인 개입이 필요하다는 주장을 현실 변화에 따른 제도와 규범의 갱신으로 구체화한다."
    },
    {
      "id": "R27",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "유학 이념을 이상 정치의 실질적 수단으로 삼자는 주장은 『노자』를 유학의 실천적 측면과 결부한 구체적 사례이다."
    },
    {
      "id": "R28",
      "type": "CONCESSION",
      "otherName": "",
      "reason": "도교가 여러 사상을 수용하여 체계화되었음에도 오징에게는 주술적인 종교에 불과했다는 어긋남을 제시한다."
    },
    {
      "id": "R29",
      "type": "BACKGROUND",
      "otherName": "",
      "reason": "사람들이 도교에 빠지는 것을 경계한 태도는 오징이 노자와 공자의 유사성을 밝히는 주석서를 쓴 계기이다."
    },
    {
      "id": "R30",
      "type": "MEANS_END",
      "otherName": "",
      "reason": "노자와 공자 학문의 유사성을 밝히려는 목적을 위해 『노자』의 내용과 구성 체제를 바꾸었다."
    },
    {
      "id": "R31",
      "type": "APPLICATION",
      "otherName": "",
      "reason": "도의 현실화로 만물이 생성된다는 원리를 인의예지와 사회 규범 및 질서의 설명에도 적용한다."
    },
    {
      "id": "R32",
      "type": "VIEW_DIFFERENCE",
      "otherName": "",
      "reason": "인의예지의 출현을 『노자』는 도의 쇠퇴로, 오징은 도의 현실화로 설명한다는 견해 차이를 제시한다."
    },
    {
      "id": "R33",
      "type": "BACKGROUND",
      "otherName": "",
      "reason": "유학과 도가 등 여러 사상이 합류하는 사조는 설혜의 『노자집해』 저술이 이루어진 시대적·사상적 배경이다."
    },
    {
      "id": "R34",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "노자가 공자도 존중했던 스승이라는 점을 이유로 노자 사상에 대한 오해를 불식해야 한다고 주장한다."
    },
    {
      "id": "R35",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "불충분한 기존 주석 때문에 노자 사상이 이단시되었다는 진단이 오해를 불식해야 한다는 주장을 뒷받침한다."
    },
    {
      "id": "R36",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "도를 도덕 본성과 천명으로 이해한 데서 노자 사상과 유학의 탐구 대상이 다르지 않다는 판단을 이끌어 낸다."
    },
    {
      "id": "R37",
      "type": "VIEW_DIFFERENCE",
      "otherName": "",
      "reason": "인의와 관련하여 오징은 도의 현실화라는 해석을, 설혜는 도덕을 근본으로 삼으라는 충고라는 해석을 제시한다."
    },
    {
      "id": "R38",
      "type": "VIEW_DIFFERENCE",
      "otherName": "",
      "reason": "도의 변화 여부에 대해 한비자는 가변성을, 오징은 불변성을 강조한다."
    },
    {
      "id": "R39",
      "type": "VIEW_DIFFERENCE",
      "otherName": "",
      "reason": "같은 『노자』의 도를 왕안석은 물질적 근원인 기로, 설혜는 도덕 본성과 천명으로 이해한다."
    },
    {
      "id": "R40",
      "type": "VIEW_AGREEMENT",
      "otherName": "",
      "reason": "한비자와 왕안석은 모두 통치의 방식이나 제도를 고정하지 말고 변화에 맞추어야 한다는 견해를 보인다."
    },
    {
      "id": "R41",
      "type": "VIEW_AGREEMENT",
      "otherName": "",
      "reason": "오징과 설혜는 모두 노자 사상과 유학이 크게 다르지 않다는 공통된 입장을 보인다."
    },
    {
      "id": "R42",
      "type": "VIEW_DIFFERENCE",
      "otherName": "",
      "reason": "『노자』를 법치 사상의 관점에서 해석한 한비자와 유학의 관점에서 해석한 송나라 이후 학자들의 입장을 비교한다."
    }
  ]
}

